import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { CodexAppParser } from "../src/codex-app.ts";

// Shape checked against ImageGenerationItem.ts generated by codex-cli 0.153.4.
// This is a schema-based fixture, not a captured user session; the payload is a tiny PNG.
const frame = JSON.parse(readFileSync(new URL("./fixtures/codex-image-completed.json", import.meta.url), "utf8"));

describe("Codex generated images", () => {
  it("forwards the image bytes, not a path inside Codex's private state", () => {
    const p = new CodexAppParser();
    const events = p.push(frame.method, frame.params);
    expect(events).toEqual([{ type: "image", id: "image-1", data: frame.params.item.result, chunk: { index: 0, total: 1 } }]);
    expect(JSON.stringify(events)).not.toContain("savedPath");
    expect(p.push(frame.method, frame.params)).toEqual([]);
  });

  it("keeps multi-megabyte images below the node WebSocket frame limit", () => {
    const result = "a".repeat(8 * 1024 * 1024);
    const events = new CodexAppParser().push(frame.method, { ...frame.params, item: { ...frame.params.item, result } });
    expect(events.length).toBeGreaterThan(1);
    expect(events.every((e) => e.type === "image" && JSON.stringify(e).length < 1024 * 1024)).toBe(true);
    expect(events.map((e: any) => e.data).join("")).toBe(result);
  });

  it("reports an empty result with savedPath without reading the private file", () => {
    const events = new CodexAppParser().push(frame.method, { item: { ...frame.params.item, result: "" } });
    expect(events).toEqual([{ type: "warning", message: expect.stringMatching(/image.*no inline data.*savedPath/i) }]);
    expect(JSON.stringify(events)).not.toContain("/private/codex");
  });

  it("does not show failed generations, view_image inputs, or MCP image previews", () => {
    const p = new CodexAppParser();
    for (const item of [
      { ...frame.params.item, status: "failed" },
      { type: "imageView", id: "view", path: "/private/photo.png" },
      { type: "mcpToolCall", id: "preview", status: "completed", result: { content: [{ type: "image", data: frame.params.item.result, mimeType: "image/png" }] } },
    ]) expect(p.push(frame.method, { item }).some((e) => e.type === "image")).toBe(false);
  });

  it("rejects an oversized result before emitting image frames", () => {
    const events = new CodexAppParser().push(frame.method, { item: { ...frame.params.item, result: "a".repeat(40 * 1024 * 1024 + 4) } });
    expect(events).toEqual([{ type: "warning", message: expect.stringContaining("30 MB") }]);
  });
});
